function commitAt(root, date, files, msg = 'work Refs #1') {
  writeFiles(root, files);
  git(root, 'add', '-A');
  const r = spawnSync('git', ['commit', '-q', '-m', msg], {
    cwd: root, encoding: 'utf8',
