"""moveback.py <pack> [--drop LEADIN]... [--from-branch LEADIN]...
Rebuild packs/<pack>/RULES.md from origin/main: drop the rule blocks whose lead-in contains
LEADIN (they stay in a kept path-scoped skill), and for --from-branch take the branch's current
block of that lead-in instead of main's (a describe-only deletion to keep). Rewrites the README's
rule table accordingly (rows by position, word counts recomputed). Prints what it did."""
import re, subprocess, sys
pack = sys.argv[1]; drops=[]; frombranch=[]
a = sys.argv[2:]
while a:
    k=a.pop(0); v=a.pop(0)
    (drops if k=='--drop' else frombranch).append(v)
def show(path): return subprocess.run(['git','show',f'origin/main:{path}'],capture_output=True,text=True,check=True).stdout
RULE=re.compile(r'^- \*\*'); HEAD=re.compile(r'^(#{2,})\s+(.+?)\s*$'); LEAD=re.compile(r'\*\*([\s\S]+?)\*\*')
def norm(t): return re.sub(r'[—–-]$','',re.sub(r'\s+',' ',re.sub(r'[`*_]','',t))).strip().strip('—–- ').strip()
def blocks(lines, starts):
    out=[]; cur=None
    for i,l in enumerate(lines):
        if starts(l): cur=[i,i]; out.append(cur)
        elif cur is not None:
            if HEAD.match(l): cur=None
            else: cur[1]=i
    res=[]
    for s,e in out:
        while e>s and not lines[e].strip(): e-=1
        text='\n'.join(lines[s:e+1]); h=HEAD.match(lines[s]); m=LEAD.search(text)
        res.append(dict(s=s,e=e,lead=norm(h.group(2) if h else m.group(1) if m else lines[s]),words=len(text.split())))
    return res
def rules(text):
    lines=text.split('\n'); b=blocks(lines,lambda l: bool(RULE.match(l)))
    return (lines, b if b else blocks(lines,lambda l: bool(HEAD.match(l))))
mainR=show(f'packs/{pack}/RULES.md'); branchR=open(f'packs/{pack}/RULES.md').read()
ml,mb=rules(mainR); bl,bb=rules(branchR)
def find(bs,sub):
    hits=[b for b in bs if sub.lower() in b['lead'].lower()]
    assert len(hits)==1, (sub, [h['lead'] for h in hits])
    return hits[0]
drop_idx=set(); repl={}
for d in drops: drop_idx.add(mb.index(find(mb,d)))
for f in frombranch: repl[mb.index(find(mb,f))]='\n'.join(bl[find(bb,f)['s']:find(bb,f)['e']+1])
# rebuild RULES.md
out=[]; i=0; skip_until=-1
for bi,b in enumerate(mb):
    out.extend(ml[i:b['s']])
    if bi in drop_idx: pass
    elif bi in repl: out.append(repl[bi])
    else: out.extend(ml[b['s']:b['e']+1])
    i=b['e']+1
out.extend(ml[i:])
text='\n'.join(out)
# drop headings with no rule left under them (bullet mode only), collapse blank runs
if any(RULE.match(l) for l in ml):
    ls=text.split('\n'); keep=[]; 
    for j,l in enumerate(ls):
        if HEAD.match(l):
            k=j+1; has=False
            while k<len(ls) and not HEAD.match(ls[k]):
                if RULE.match(ls[k]): has=True; break
                k+=1
            if not has: 
                # also drop its preamble lines up to next heading
                keep.append(None); continue
        keep.append(l)
    # remove None and the non-rule lines following a removed heading
    res=[]; dropping=False
    for l in keep:
        if l is None: dropping=True; continue
        if dropping and (HEAD.match(l) or RULE.match(l)): dropping=False
        if not dropping: res.append(l)
    text='\n'.join(res)
text=re.sub(r'\n{3,}','\n\n',text).rstrip('\n')+'\n'
open(f'packs/{pack}/RULES.md','w').write(text)
nl,nb=rules(text)
print(f'{pack}: main {len(mb)} rules -> {len(nb)} (dropped {len(drop_idx)}, from-branch {len(repl)})')
