try: mainD=show(f'packs/{pack}/README.md')
except subprocess.CalledProcessError: print('no README on main'); sys.exit()
dl=mainD.split('\n'); rows=[]; inidx=False; start=None
for j,l in enumerate(dl):
    if not l.startswith('|'):
        if inidx: break
