readme=dl[:rows[0]]+newrows+dl[rows[-1]+1:]
open(f'packs/{pack}/README.md','w').write('\n'.join(readme))
print(f'README rows: {len(rows)} -> {len(newrows)} (from main README; skills table/prose must be re-added by hand)')
